import { test, expect, Page } from '@playwright/test';

test.describe('Footer Links Navigation', () => {
  let page: Page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000');
  });

  test('should navigate to About page when clicking About link in footer', async () => {
    // Scroll to footer
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Click About link in footer
    const aboutLink = page.getByRole('link', { name: /about/i }).last();
    await aboutLink.click();

    // Verify navigation to About page
    await expect(page).toHaveURL(/.*about/i);
    await expect(page.getByRole('heading', { name: /about/i })).toBeVisible();
  });

  test('should navigate to Contact page when clicking Contact link in footer', async () => {
    // Scroll to footer
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Click Contact link in footer
    const contactLink = page.getByRole('link', { name: /contact/i }).last();
    await contactLink.click();

    // Verify navigation to Contact page
    await expect(page).toHaveURL(/.*contact/i);
    await expect(page.getByRole('heading', { name: /contact/i })).toBeVisible();
  });

  test('should navigate to Privacy Policy page when clicking Privacy Policy link in footer', async () => {
    // Scroll to footer
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Click Privacy Policy link in footer
    const privacyLink = page.getByRole('link', { name: /privacy policy/i }).last();
    await privacyLink.click();

    // Verify navigation to Privacy Policy page
    await expect(page).toHaveURL(/.*privacy/i);
    await expect(page.getByRole('heading', { name: /privacy/i })).toBeVisible();
  });

  test('should navigate to Terms of Service page when clicking Terms link in footer', async () => {
    // Scroll to footer
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Click Terms of Service link in footer
    const termsLink = page.getByRole('link', { name: /terms/i }).last();
    await termsLink.click();

    // Verify navigation to Terms page
    await expect(page).toHaveURL(/.*terms/i);
    await expect(page.getByRole('heading', { name: /terms/i })).toBeVisible();
  });

  test('should open social media links in new tab', async () => {
    // Scroll to footer
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Get all social media links
    const socialLinks = page.getByRole('link', { name: /facebook|twitter|linkedin|instagram/i });
    const count = await socialLinks.count();

    // Verify at least one social media link exists
    expect(count).toBeGreaterThan(0);

    // Check first social media link has target="_blank"
    const firstSocialLink = socialLinks.first();
    const target = await firstSocialLink.getAttribute('target');
    expect(target).toBe('_blank');
  });

  test('should have all footer links with proper href attributes', async () => {
    // Scroll to footer
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));

    // Get all footer links
    const footerSection = page.getByRole('contentinfo');
    const links = footerSection.getByRole('link');
    const linkCount = await links.count();

    // Verify footer has links
    expect(linkCount).toBeGreaterThan(0);

    // Verify each link has href attribute
    for (let i = 0; i < linkCount; i++) {
      const href = await links.nth(i).getAttribute('href');
      expect(href).toBeTruthy();
      expect(href).not.toBe('#');
    }
  });

  test('should maintain footer visibility and accessibility across pages', async () => {
    // Scroll to footer on home page
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    const footerHome = page.getByRole('contentinfo');
    await expect(footerHome).toBeVisible();

    // Navigate to another page
    const aboutLink = page.getByRole('link', { name: /about/i }).last();
    await aboutLink.click();
    await page.waitForLoadState('networkidle');

    // Scroll to footer on new page
    await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
    const footerAbout = page.getByRole('contentinfo');
    await expect(footerAbout).toBeVisible();

    // Verify footer links are still accessible
    const footerLinks = footerAbout.getByRole('link');
    expect(await footerLinks.count()).toBeGreaterThan(0);
  });
});
